#include <stdio.h>
/* ex07：成组链接法——UNIX 的空闲块管理
 * 把空闲块分成若干组，超级块里存「当前组的块数与块号」，每组的最后一块
 * 再存「下一组的块数与块号」，形成一条链。
 * 分配：从当前组取；取空则把最后一块里记的下一组读进来。
 * 回收：当前组满则把当前组信息写进回收块，再以它为新的当前组。*/
typedef struct {
    int count;        /* 当前组里的空闲块数 */
    int blocks[5];    /* 组内块号（示例用小容量） */
} Group;

static Group sp;      /* 超级块里那部分 */

static int alloc(void) {
    if (sp.count == 0) return -1;
    return sp.blocks[--sp.count];
}

int main(void) {
    /* 初始：当前组有 4 个空闲块，最后一个块 900 里记着下一组 */
    sp.count = 4;
    sp.blocks[0] = 800; sp.blocks[1] = 801;
    sp.blocks[2] = 802; sp.blocks[3] = 803;

    printf("初始超级块: 当前组 %d 个空闲块 -> ", sp.count);
    for (int i = 0; i < sp.count; i++) printf("%d ", sp.blocks[i]);
    printf("\n--------------------------------------------------\n");

    printf("%-8s %-10s %-12s %s\n", "操作", "返回块号", "剩余块数", "说明");
    for (int i = 0; i < 6; i++) {
        int b = alloc();
        if (b >= 0)
            printf("%-8s %-10d %-12d %s\n", "分配", b, sp.count,
                   sp.count == 0 ? "组已空：下次分配要读下一组" : "");
        else
            printf("%-8s %-10s %-12d %s\n", "分配", "失败", sp.count,
                   "超级块为空且链已到末端 -> ENOSPC");
    }
    printf("--------------------------------------------------\n");
    printf("结论: 成组链接把「空闲块号」也存进空闲块本身，超级块只需存一组的量；\n");
    printf("      这样既省内存，又能一次拿到一批连续块号（适合大文件预分配）。\n");
    return 0;
}
